using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Threading;
using Avalonia.VisualTree;
using OfficeIMO.Project;
using System.Text.Json;
namespace ProjectDesk;
internal static class AutoSchedulingValidation {
 public static int ModelChecks(string output){
  Directory.CreateDirectory(output);int checks=0;void Assert(bool ok,string why){if(!ok)throw new Exception(why);checks++;}
  using var s=new ProjectSession();s.NewProject("Automatic dates",new DateTime(2026,10,16,8,0,0));int p=s.AddTask("Predecessor"),a=s.AddTask("Activity A"),b=s.AddTask("Activity B");
  void Dates(int uid,DateTime start,DateTime finish,string message){var t=s.Document!.Tasks.GetByUid(uid);Assert(t.Start==start&&t.Finish==finish,$"{message}: {t.Start:o} / {t.Finish:o}");}
  Dates(p,new(2026,10,16,8,0,0),new(2026,10,16,17,0,0),"Unlinked auto task");s.EditText(a,"Predecessors","1fs");Dates(a,new(2026,10,19,8,0,0),new(2026,10,19,17,0,0),"Weekend FS");s.EditText(b,"Predecessors","2FS");s.EditText(a,"Duration","2d");Dates(a,new(2026,10,19,8,0,0),new(2026,10,20,17,0,0),"Duration change");Dates(b,new(2026,10,21,8,0,0),new(2026,10,21,17,0,0),"Successor propagation");s.EditText(p,"Duration","2d");Dates(a,new(2026,10,20,8,0,0),new(2026,10,21,17,0,0),"Predecessor duration change");Dates(b,new(2026,10,22,8,0,0),new(2026,10,22,17,0,0),"Chain propagation");s.EditText(a,"Predecessors","1FS+1d");Dates(a,new(2026,10,21,8,0,0),new(2026,10,22,17,0,0),"FS positive lag");s.EditText(a,"Duration","1d");s.EditText(a,"Predecessors","1FS-4h");Dates(a,new(2026,10,19,13,0,0),new(2026,10,20,12,0,0),"FS lead and lunch break");s.EditText(a,"Predecessors","1SS");Dates(a,new(2026,10,16,8,0,0),new(2026,10,16,17,0,0),"SS");s.EditText(a,"Predecessors","1FF");Dates(a,new(2026,10,19,8,0,0),new(2026,10,19,17,0,0),"FF");s.EditText(a,"Predecessors","1SF");var sf=s.Document!.Tasks.GetByUid(a);Assert(sf.Finish<=s.Document.Tasks.GetByUid(p).Start&&s.Document.Calendar!.WorkingMinutesBetween(sf.Finish!.Value,s.Document.Tasks.GetByUid(p).Start!.Value)==0,"SF finish bound");
  s.EditText(a,"TaskMode","manual");var manualStart=s.Document.Tasks.GetByUid(a).Start;var manualFinish=s.Document.Tasks.GetByUid(a).Finish;s.EditText(a,"Predecessors","1FS");Assert(s.Document.Tasks.GetByUid(a).Start==manualStart&&s.Document.Tasks.GetByUid(a).Finish==manualFinish,"Manual dates were overwritten");s.EditText(a,"TaskMode","auto");Dates(a,new(2026,10,20,8,0,0),new(2026,10,20,17,0,0),"Switch manual to automatic");
  int position=s.HistoryPosition;var previous=s.Document.Tasks.GetByUid(a).Start;try{s.EditText(p,"Predecessors","3FS");Assert(false,"Cycle accepted");}catch(InvalidOperationException){checks++;}Assert(s.HistoryPosition==position&&s.Document!.Tasks.GetByUid(a).Start==previous,"Rejected link changed dates/history");
  s.EditCells([new(a,"Predecessors","1FS+2d")]);Dates(a,new(2026,10,22,8,0,0),new(2026,10,22,17,0,0),"Bulk predecessor edit");s.PasteTasks(a,["Predecessors"],"Predecessors","1FS");Dates(a,new(2026,10,20,8,0,0),new(2026,10,20,17,0,0),"Pasted predecessor edit");s.UnlinkTasks([p,a]);Dates(a,new(2026,10,16,8,0,0),new(2026,10,16,17,0,0),"Unlink returns to project start");
  s.SetCalendarException(new(s.Document!.Calendar!.Uid,"Monday holiday",new(2026,10,19),new(2026,10,19),[],false));s.EditText(p,"Duration","1d");s.LinkTasks(p,a,ProjectDependencyType.FinishToStart,ProjectDuration.WorkingDays(0));Dates(a,new(2026,10,20,8,0,0),new(2026,10,20,17,0,0),"Holiday FS");
  s.EditText(a,"Start","2026-11-02 08:00");Dates(a,new(2026,11,2,8,0,0),new(2026,11,2,17,0,0),"Later explicit start calculates finish");s.EditText(a,"Finish","2026-11-04 17:00");Dates(a,new(2026,11,4,8,0,0),new(2026,11,4,17,0,0),"Later explicit finish calculates start");
  int child=s.AddTask("Child",parentUid:p);var parent=s.Document!.Tasks.GetByUid(p);Assert(parent.Start==s.Document.Tasks.GetByUid(child).Start&&parent.Finish==s.Document.Tasks.GetByUid(child).Finish,"Summary dates did not roll up");
  var fixture=Path.Combine(output,"auto-date-model-"+Guid.NewGuid()+".mpp");s.SaveCopy(fixture,true);Console.WriteLine($"PASS: {checks} automatic model checks; FS/SS/FF/SF, lag/lead, weekends/holiday, duration/chain, manual/auto, atomic invalid edit, paste, unlink and summary dates.");return 0;
 }
 public static int Run(string file,string output){
  Directory.CreateDirectory(output);AppBuilder.Configure<DesktopApp>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).SetupWithoutStarting();int checks=0;
  void Assert(bool ok,string why){if(!ok)throw new Exception(why);checks++;}
  void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick(3);Dispatcher.UIThread.RunJobs();}
  using var session=new ProjectSession();session.Open(file);var before=session.Tasks.ToDictionary(t=>t.Uid,t=>(t.Start,t.Finish));var totals=session.Resources.Select(r=>(r.Uid,r.Work,r.ActualWork,r.Cost,r.ActualCost)).ToArray();var originalBytes=File.ReadAllBytes(file);
  var predecessor=session.Tasks.First(t=>!t.IsSummary&&t.Start.HasValue&&t.Finish.HasValue&&t.IsActive!=false);int predUid=predecessor.Uid;var finish=predecessor.Finish!.Value;
  var window=new PlannerWindow(session,Path.Combine(output,"preferences.json"));string lastError="";window.Sheet.Error+=message=>lastError=message;window.Show();Pump();window.Sheet.InsertBlankRow(false);Pump();var nameEditor=window.Sheet.Grid.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="CellTextBox"&&t.IsVisible);nameEditor.Text="Activity A auto test";Assert(window.Sheet.Grid.CommitEdit(),"Blank-row name commit failed: "+lastError);Pump();int uid=session.Tasks.Single(t=>t.Name=="Activity A auto test").Uid;
  Assert(session.Document!.Tasks.GetByUid(uid).Start.HasValue&&session.Document.Tasks.GetByUid(uid).Finish.HasValue,"New imported auto task has no start/finish dates");
  void Edit(string key,string text){var row=window.Sheet.Grid.ItemsSource!.OfType<TaskTableRow>().Single(r=>r.Uid==uid);window.Sheet.Grid.SelectedItem=row;window.Sheet.Grid.CurrentColumn=window.Sheet.Grid.Columns.Single(c=>Equals(c.Header,window.Sheet.Catalogue.Single(s=>s.Key==key).Title));window.Sheet.Grid.ScrollIntoView(row,window.Sheet.Grid.CurrentColumn);window.Sheet.Grid.Focus();Assert(window.Sheet.Grid.BeginEdit(),"Could not edit "+key);Pump();var editor=window.Sheet.Grid.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="CellTextBox"&&t.IsVisible);editor.Text=text;Assert(window.Sheet.Grid.CommitEdit(),"Could not commit "+key);Pump();}
  Edit("TaskMode","auto");Edit("Duration","2d");Edit("Predecessors",session.Document.Tasks.GetByUid(predUid).DisplayId+"fs");
  var task=session.Document.Tasks.GetByUid(uid);var calendar=task.Calendar??session.Document.Calendar!;var expectedStart=Enumerable.Range(0,36600).SelectMany(day=>calendar.GetWorkingIntervals(finish.Date.AddDays(day))).Where(range=>range.Finish>finish).Select(range=>range.Start>finish?range.Start:finish).First();var expectedFinish=calendar.AddWorkingMinutes(expectedStart,2*(session.Document.Settings.MinutesPerDay??480));
  Assert(task.Start==expectedStart&&task.Finish==expectedFinish,$"FS auto dates wrong: {task.Start:o} / {task.Finish:o}, expected {expectedStart:o} / {expectedFinish:o}");var displayed=window.Sheet.Grid.ItemsSource!.OfType<TaskTableRow>().Single(r=>r.Uid==uid);Assert(!string.IsNullOrWhiteSpace(displayed.Cells["Start"])&&!string.IsNullOrWhiteSpace(displayed.Cells["Finish"]),"Calculated dates did not reach grid cells");Assert(window.Gantt.VisibleNodes().Any(n=>n.Uid==uid),"Automatically dated new task has no Gantt bar");
  foreach(var item in before)Assert(session.Document.Tasks.GetByUid(item.Key).Start==item.Value.Start&&session.Document.Tasks.GetByUid(item.Key).Finish==item.Value.Finish,"Unrelated imported task dates changed");Assert(totals.SequenceEqual(session.Resources.Select(r=>(r.Uid,r.Work,r.ActualWork,r.Cost,r.ActualCost))),"Automatic dates changed stored resource totals");
  session.Undo();Assert(!session.Document.Dependencies.Any(l=>l.Successor.Uid==uid),"Undo did not remove predecessor link");session.Redo();Assert(session.Document.Tasks.GetByUid(uid).Start==expectedStart,"Redo did not restore calculated dates");window.RefreshForValidation();Pump();using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"auto-fs-grid.png"));
  var path=Path.Combine(output,"auto-fs-"+Guid.NewGuid()+".mpp");var assessment=session.AssessSave(path);assessment.ThrowIfErrors();session.SaveCopy(path,true);using(var reopened=ProjectDocument.Load(path)){var saved=reopened.Tasks.GetByUid(uid);Assert(saved.Start==expectedStart&&saved.Finish==expectedFinish,"Export/reopen lost automatic dates");}Assert(originalBytes.SequenceEqual(File.ReadAllBytes(file)),"Original file changed");File.WriteAllText(Path.Combine(output,"expected.json"),JsonSerializer.Serialize(new{file=path,uid,start=expectedStart,finish=expectedFinish,predUid},new JsonSerializerOptions{WriteIndented=true}));
  window.CloseForValidation();Console.WriteLine($"PASS: {checks} auto-date checks; blank insertion / auto / duration / lower-case FS / visible dates and Gantt / Undo+Redo / preserved imported dates+totals / save+reopen.");return 0;
 }
}
